import sys

def longestString(arr):
    s = set(arr)
    valid_strings = []

    for word in arr:
        is_valid = True
        for i in range(1, len(word)):
            if word[:i] not in s:
                is_valid = False
                break
        if is_valid:
            valid_strings.append(word)

    if not valid_strings:
        return ""

    valid_strings.sort(key=lambda x: (-len(x), x))
    return valid_strings[0]

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        print("")
        return

    result = longestString(input_data)
    print(result)

if __name__ == "__main__":
    main()
